    },
    {
      "condition_id": "instantaneous_feedback",
      "statement": "Finite propagation time of current fluctuations is neglected; feedback is considered instantaneous.",
      "anchors": [
        {
          "line_start": 148,
          "line_end": 148,
          "support": "We neglect here the finite propagation time of current fluctuations when addressing feedback, which is considered instantaneous."
        }
      ]
    },
    {
      "condition_id": "channel_count_N1",
      "statement": "The chain has exactly N=1 chiral ballistic channel per link.",
      "anchors": [
        {
          "line_start": 121,
          "line_end": 121,
          "support": "Remarkably, the decay length Delta as well as the diffusive term in Eq. (Heat_diffusion) vanish for N=1, where each island k has a temperature T_mid."
        },
        {
          "line_start": 133,
          "line_end": 133,
          "support": "In the singular case N=1 the heat flow retains its non-local contribution only due to the SN mode."
        },
        {
          "line_start": 146,
          "line_end": 146,
          "support": "For N=1, the ratio remains equal to 1."
        }
      ]
    },
    {
      "condition_id": "channel_count_N2",
      "statement": "The chain has exactly N=2 chiral ballistic channels per link.",
      "anchors": [
        {
          "line_start": 124,
          "line_end": 124,
          "support": "The agreement with the long chain approximation is good when the number of channels is small (here N=1,2)."
        },
        {
          "line_start": 146,
          "line_end": 146,
          "support": "For N=2, the Lorenz ratio grows as M^{1/2} provided M >> N."
        }
      ]
    }
  ],
